function verHoisting() {
  console.log(typeof mensagem); // 'undefined' — var foi içada (sem erro)

  var mensagem = 'oi';

  try {
    console.log(valor);   // ReferenceError: valor está na zona morta temporal
  } catch {
    console.log('valor ainda não está pronta');
  }

  let valor = 10;         // só a partir daqui 'valor' existe
  return mensagem + valor;
}

